// ---------- utilidades de limpieza ----------
function aFecha(txt) {
  if (!txt) return null;
  const t = String(txt).trim();
  let m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);   // 02/09/2026
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2})$/);       // 7/9/26
  if (m) return '20' + m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  return null;
}

function aNumero(txt) {
  if (txt === null || txt === undefined) return null;
  let t = String(txt).trim().replace(/[€\s]/g, '');     // quita € y espacios
  if (t === '') return null;
  if (t.indexOf(',') >= 0 && t.indexOf('.') >= 0) t = t.replace(/\./g, '').replace(',', '.'); // 1.842,30
  else if (t.indexOf(',') >= 0) t = t.replace(',', '.');                                        // 4,5
  const n = Number(t);
  return isNaN(n) ? null : n;
}

function clave(txt) {
  return String(txt || '').trim().replace(/\s+/g, ' ').toLowerCase();
}

// ---------- lo que ya hay en la app ----------
const existentes = $('Apartados en la app').all().map(i => i.json).filter(x => x && x.id);
const abonosYa   = $('Abonos en la app').all().map(i => i.json).filter(x => x && x.id);

// ---------- filas del CSV ----------
const filas = $input.all().map(i => i.json);
const salida = [];
const yaVisto = {};

for (let n = 0; n < filas.length; n++) {
  const f = filas[n];
  const linea = n + 2;   // la línea 1 es la cabecera

  if (!f.fecha && !f.cliente) continue;   // fila vacía

  const fecha  = aFecha(f.fecha);
  const precio = aNumero(f.precio);
  const abono  = aNumero(f.abono);
  const notas  = String(f.notas || '');
  const par    = clave(f.cliente) + '|' + clave(f.modelo);

  if (!f.cliente || !f.modelo) {
    salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Falta el cliente o el modelo' } });
    continue;
  }
  if (!fecha) {
    salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Fecha ilegible: "' + f.fecha + '"' } });
    continue;
  }
  if (precio === null || abono === null) {
    salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Importe ilegible (precio "' + f.precio + '", abono "' + f.abono + '")' } });
    continue;
  }

  const esAbono = yaVisto[par] === true || /abono|liquidado/i.test(notas);

  if (!esAbono) {
    // ---- NUEVO APARTADO ----
    yaVisto[par] = true;
    if (abono < 5) {
      salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Abono inicial de ' + abono.toFixed(2) + ' EUR: por debajo del mínimo de 5 EUR (la app lo rechazaría con 422)' } });
      continue;
    }
    if (abono > precio) {
      salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'El abono inicial (' + abono.toFixed(2) + ') supera el precio (' + precio.toFixed(2) + ')' } });
      continue;
    }
    const dup = existentes.find(e =>
      clave(e.cliente) === clave(f.cliente) &&
      clave(e.producto) === clave(f.modelo) &&
      e.fecha === fecha
    );
    if (dup) {
      salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Ya estaba cargado en la app (apartado #' + dup.id + '): no se duplica' } });
      continue;
    }
    salida.push({ json: {
      tipo: 'apartado', linea: linea,
      payload: {
        cliente: f.cliente,
        telefono: String(f.telefono || '').trim(),
        producto: f.modelo,
        talla: String(f.talla || '').trim(),
        precio: precio,
        abono_inicial: abono,
        fecha: fecha
      }
    }});
  } else {
    // ---- ABONO A UN APARTADO ----
    const padre = existentes.find(e =>
      clave(e.cliente) === clave(f.cliente) &&
      clave(e.producto) === clave(f.modelo)
    );
    if (!padre) {
      salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Aún no existe el apartado al que pertenece este abono: se cargará en la próxima ejecución' } });
      continue;
    }

    // ====== ARREGLO: ¿ya estaba cargado? ======
    // Señal 1 (la más fiable): el total que Marisa anotó en el Excel es "precio - resta".
    // Si la app ya acumula ese importe, este abono ya está aplicado.
    const resta = aNumero(f.resta);
    const totalEsperado = (resta === null) ? null : precio - resta;
    const yaAcumulado = (totalEsperado !== null) && (Number(padre.abonado || 0) >= totalEsperado - 0.001);

    // Señal 2: existe un abono igual (mismo día, mismo importe)
    const repetido = yaAcumulado || abonosYa.some(a =>
      Number(a.apartado_id) === Number(padre.id) &&
      a.fecha === fecha &&
      Number(a.importe) === abono
    );
    // ====== fin del arreglo ======

    if (repetido) {
      salida.push({ json: { tipo: 'dudoso', linea: linea, motivo: 'Ese abono ya estaba en el apartado #' + padre.id + ': no se duplica' } });
      continue;
    }
    salida.push({ json: {
      tipo: 'abono', linea: linea, apartado_id: padre.id,
      payload: { importe: abono, fecha: fecha }
    }});
  }
}
// Los dudosos no viajan como items: se guardan como campo para no bifurcar el flujo.
// Así el informe siempre se envía, aunque no haya nada que crear.
const listaDudosos = salida
  .filter(s => s.json.tipo === 'dudoso')
  .map(s => ({ linea: s.json.linea, motivo: s.json.motivo }));

const aCrear = salida.filter(s => s.json.tipo !== 'dudoso');

// Si no hay nada que crear, mandamos UN item para que el informe salga igualmente
const finales = aCrear.length ? aCrear : [{ json: { tipo: 'nada', payload: null } }];

for (const f of finales) f.json.dudosos = listaDudosos;

return finales;

// Los dudosos: viajan como campo, y 'Limpiar y clasificar' SIEMPRE se ejecuta
const plan = $('Limpiar y clasificar').all().map(i => i.json);
const dudosos = (plan[0] && plan[0].dudosos) ? plan[0].dudosos : [];
const planeados = plan.filter(x => x.tipo === 'apartado');
const abonosPlan = plan.filter(x => x.tipo === 'abono');

// Lo que la app CREÓ de verdad. Si 'Crear en la app' no llegó a ejecutarse, aquí no hay nada.
let creados = [];
try {
  creados = $('Crear en la app').all().map(i => i.json).filter(x => x && x.id);
} catch (e) {
  creados = [];
}
const cApartados = creados.filter(x => x.producto !== undefined);
const cAbonos = creados.filter(x => x.apartado_id !== undefined);

const yaCargados = dudosos.filter(d => d.motivo.indexOf('no se duplica') >= 0);
const decidir = dudosos.filter(d => yaCargados.indexOf(d) === -1);

const l = [];
l.push('MIGRACIÓN DEL EXCEL - ' + $now.toFormat('dd/MM/yyyy HH:mm'));
l.push('');
l.push('REALMENTE CREADO EN LA APP:');
l.push('  Apartados: ' + cApartados.length + '  (planeados ' + planeados.length + ')');
l.push('  Abonos: ' + cAbonos.length + '  (planeados ' + abonosPlan.length + ')');
l.push('');
l.push('YA ESTABAN CARGADOS (no se ha duplicado): ' + yaCargados.length);
l.push('');
l.push('PARA QUE DECIDAS (' + decidir.length + '):');
if (decidir.length === 0) l.push('  (ninguno)');
else for (const d of decidir) l.push('  Linea ' + d.linea + ': ' + d.motivo);
l.push('');
l.push('Revisa en la app y dime que hacemos con los casos dudosos.');

return [{ json: {
  asunto: 'Migración: ' + cApartados.length + ' apartados y ' + cAbonos.length + ' abonos reales, ' + decidir.length + ' por revisar',
  texto: l.join('\n')
}}];
